insert into activities (id, lesson_id, position, type, concept, points, counts_toward_unlock, content) values
  ('7c0017f0-fe74-5eb1-8ab2-8e061944c996', '376ed48d-9299-5e3d-8b4d-86215a437ffe', 2, 'check', 'class norms', 1, true,
   '{"prompt":"You want an AI chatbot to help write a birthday invitation for a friend. What fits our class norms?","choices":[{"id":"a","label":"Paste in your friend''s full name, home address and phone number"},{"id":"b","label":"Leave out the address and use made-up details"},{"id":"c","label":"Ask the chatbot to find your friend''s address online"},{"id":"d","label":"Tell everyone the AI wrote it by itself with no help"}],"answer":"b","explanation":"Protect personal information. An invitation can be drafted with made-up details, and you can add the real ones yourself later."}'::jsonb)
