insert into activities (id, lesson_id, position, type, concept, points, counts_toward_unlock, content) values
  ('ac9bb104-1742-55ea-9ac5-e997a84ee523', '454dc64b-ee31-5716-abc8-cd93ac7df31e', 1, 'pretest', 'pretest', 0, true,
   '{"items":[{"id":"p1","concept":"computer parts","prompt":"Which part of a computer follows a program''s instructions to process data?","choices":[{"id":"a","label":"Keyboard"},{"id":"b","label":"CPU (processor)"},{"id":"c","label":"Monitor"},{"id":"d","label":"Speaker"}],"answer":"b"},{"id":"p2","concept":"binary","prompt":"Computers store text, pictures and sound using:","choices":[{"id":"a","label":"Bits: 0s and 1s"},{"id":"b","label":"Only the letters A to Z"},{"id":"c","label":"Tiny printed photos"},{"id":"d","label":"Recorded sound waves"}],"answer":"a"},{"id":"p3","concept":"early vs modern computers","prompt":"Charles Babbage proposed the Difference Engine in 1822. What was it?","choices":[{"id":"a","label":"A steam-powered robot"},{"id":"b","label":"An early electronic laptop"},{"id":"c","label":"A mechanical calculator built with gears"},{"id":"d","label":"The first smartphone"}],"answer":"c"},{"id":"p4","concept":"early vs modern computers","prompt":"Compared with early computers, modern computers are usually:","choices":[{"id":"a","label":"Bigger and slower"},{"id":"b","label":"Only able to do basic math"},{"id":"c","label":"Programmed only with punch cards"},{"id":"d","label":"Smaller, faster, and able to run many different programs"}],"answer":"d"},{"id":"p5","concept":"what is AI","prompt":"Which is the best description of artificial intelligence (AI)?","choices":[{"id":"a","label":"Any machine that runs on electricity"},{"id":"b","label":"Computer systems that do tasks like recognizing patterns, understanding language, or making predictions"},{"id":"c","label":"A robot that thinks exactly like a person"},{"id":"d","label":"Anything that is connected to the internet"}],"answer":"b"},{"id":"p6","concept":"AI or not","prompt":"Which of these is most likely using AI?","choices":[{"id":"a","label":"A basic calculator"},{"id":"b","label":"A simple light switch"},{"id":"c","label":"Movie suggestions on a streaming app"},{"id":"d","label":"A basic vending machine"}],"answer":"c"},{"id":"p7","concept":"how AI learns","prompt":"Many AI systems learn by:","choices":[{"id":"a","label":"Finding patterns in lots of training examples"},{"id":"b","label":"Reading people''s minds"},{"id":"c","label":"Guessing randomly every time"},{"id":"d","label":"Following one fixed rule that never changes"}],"answer":"a"},{"id":"p8","concept":"AI limits","prompt":"An AI chatbot gives you an answer for your science homework. What should you do?","choices":[{"id":"a","label":"Trust it, because AI is never wrong"},{"id":"b","label":"Copy it exactly without reading it"},{"id":"c","label":"Check it with a trusted source, because AI can make mistakes"},{"id":"d","label":"Ask it the same question until it says what you want"}],"answer":"c"}],"title":"What do you already know?"}'::jsonb)
