insert into activities (id, lesson_id, position, type, concept, points, counts_toward_unlock, content) values
  ('820c9590-e9a7-5061-8e42-f0075ba0f62d', '5580fd8d-6f89-59c9-ac7f-ebda6837f46a', 1, 'content', 'computer parts', 0, true,
   '{"markdown":"## What is a computer?\n\nTake a second and think: what makes something a computer?\n\nA **computer** is an electronic device that processes data and performs tasks based on instructions.\nThe instructions are called a **program**.\n\nComputers are everywhere. We use them at school, at work, and for fun.\nWe use them to learn, create, communicate, and solve problems.\n\n### What can a computer do?\n\n- Do hard tasks very quickly, like millions of math problems in a second\n- Store huge amounts of information, like photos, music and schoolwork\n- Connect to networks like the internet\n- Help people communicate, with messages, video calls and email\n\nA computer does not think for itself. It follows its program, one instruction at a time, very fast.","title":"What is a computer?"}'::jsonb)
