insert into activities (id, lesson_id, position, type, concept, points, counts_toward_unlock, content) values
  ('9d49af42-ed9c-52d7-bbb1-e93aa946e864', '5580fd8d-6f89-59c9-ac7f-ebda6837f46a', 3, 'interactive_html', 'computer parts', 1, true,
   '{"html":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>Build the Machine</title>\n<style>\n:root{--accent:#5b2a86;--accent-soft:#f3ecf9;--ink:#1b1b22;--muted:#464654;--line:#c4c4cf;--bg:#fff;--panel:#f5f5f8;--ok:#14532d;--ok-bg:#e4f4e9;--no:#8a1c1c;--no-bg:#fcebeb;--focus:#1d4ed8;color-scheme:light}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%}\nbody{margin:0;background:var(--bg);color:var(--ink);font:1.0625rem/1.55 system-ui,-apple-system,\"Segoe UI\",Roboto,Arial,sans-serif}\nmain{max-width:52rem;margin:0 auto;padding:16px 16px 28px}\nh1{font-size:1.5rem;line-height:1.25;margin:.25rem 0 .5rem}\nh2{font-size:1.2rem;line-height:1.3;margin:1.5rem 0 .5rem}\np{margin:.5rem 0}\nul,ol{margin:.5rem 0;padding-left:1.4rem}\n.kicker{margin:0;font-size:1rem;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--accent)}\n.lede{color:var(--muted)}\n.note{background:var(--panel);border-radius:12px;padding:12px 14px;margin:12px 0}\n.note>:first-child{margin-top:0}.note>:last-child{margin-bottom:0}\nfieldset{border:1px solid var(--line);border-radius:12px;padding:12px 14px 14px;margin:0 0 16px;min-width:0}\nlegend{float:left;width:100%;padding:0;margin:0 0 4px;font-weight:700;line-height:1.4}\nlegend+*{clear:both}\n.opts{display:grid;grid-template-columns:repeat(auto-fill,minmax(8.5rem,1fr));gap:8px;margin-top:8px}\n.opt{display:flex;align-items:center;gap:10px;min-height:48px;padding:8px 12px;border:2px solid var(--line);border-radius:10px;cursor:pointer;background:var(--bg);line-height:1.3}\n.opt input{width:22px;height:22px;margin:0;flex:none;accent-color:var(--accent);cursor:pointer}\n.opt:hover{border-color:var(--accent)}\n.opt:has(input:checked){border-color:var(--accent);background:var(--accent-soft)}\n.opt:has(.r:checked){border-color:var(--ok);background:var(--ok-bg)}\n.opt:has(.w:checked){border-color:var(--no);background:var(--no-bg)}\ninput:focus-visible{outline:3px solid var(--focus);outline-offset:2px}\n.opt:has(input:focus-visible){outline:3px solid var(--focus);outline-offset:2px}\n.fb{display:none;margin:10px 0 0;padding:10px 12px;border-radius:8px;border-left:6px solid}\n.fb.ok{background:var(--ok-bg);color:var(--ok);border-color:var(--ok)}\n.fb.no{background:var(--no-bg);color:var(--no);border-color:var(--no)}\n.fb.maybe{background:var(--accent-soft);color:var(--accent);border-color:var(--accent)}\n.sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}\n@media (prefers-reduced-motion:reduce){*,*::before,*::after{transition:none!important;animation:none!important}}\nfieldset:has(.r:checked)>.fb.ok,fieldset:has(.w:checked)>.fb.no{display:block}\n.step-n{display:inline-block;min-width:1.9rem;margin-right:6px;padding:0 6px;border-radius:999px;background:var(--accent);color:#fff;text-align:center}\n.machine{display:grid;grid-template-columns:1fr auto 1fr auto 1fr;align-items:center;gap:6px;margin:12px 0 4px}\n.part{display:flex;flex-direction:column;justify-content:center;min-height:64px;padding:8px 6px;border:2px dashed var(--line);border-radius:12px;text-align:center;color:var(--muted);line-height:1.25;transition:background .25s,color .25s,border-color .25s}\n.part b{display:block;color:var(--ink)}\n.part span{font-size:1rem}\n.arrow{font-size:1.4rem;color:var(--muted);text-align:center}\n.below{grid-column:1/-1;position:relative;display:grid;grid-template-columns:1fr 1fr;gap:12px;max-width:24rem;width:100%;justify-self:center;padding-top:34px}\n.below::before{content:\"\";position:absolute;top:-6px;left:50%;height:22px;border-left:2px solid var(--muted)}\n.below::after{content:\"\";position:absolute;top:16px;left:calc(25% - 3px);right:calc(25% - 3px);border-top:2px solid var(--muted)}\n.below .part{position:relative}\n.below .part::before{content:\"\";position:absolute;top:-20px;left:50%;height:18px;border-left:2px solid var(--muted)}\n.two-way{grid-column:1/-1;margin:0;text-align:center;color:var(--muted);font-size:1rem}\nbody:has(#s1 .r:checked) .p-key,body:has(#s2 .r:checked) .p-cpu,body:has(#s3 .r:checked) .p-ram,body:has(#s4 .r:checked) .p-scr,body:has(#s5 .r:checked) .p-ssd{border:2px solid var(--accent);background:var(--accent);color:#fff}\nbody:has(#s1 .r:checked) .p-key b,body:has(#s2 .r:checked) .p-cpu b,body:has(#s3 .r:checked) .p-ram b,body:has(#s4 .r:checked) .p-scr b,body:has(#s5 .r:checked) .p-ssd b{color:#fff}\n.done{display:none}\nbody:has(#s1 .r:checked):has(#s2 .r:checked):has(#s3 .r:checked):has(#s4 .r:checked):has(#s5 .r:checked) .done{display:block}\n@media (max-width:420px){.part span{display:none}.part{min-height:52px}}\n</style>\n</head>\n<body>\n<main>\n<p class=\"kicker\">AI Academy - Module 1</p>\n<h1>Build the Machine</h1>\n<p class=\"lede\">Trace one action: <strong>you type your name and save it.</strong> For each step, pick the part of the computer that does the job. You get feedback right away, so it is fine to guess and try again.</p>\n\n<fieldset id=\"s1\">\n<legend><span class=\"step-n\">1</span>Input: you press keys to type your name.</legend>\n<div class=\"opts\">\n<label class=\"opt\"><input type=\"radio\" name=\"s1\" class=\"r\"> Keyboard</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s1\" class=\"w\"> CPU</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s1\" class=\"w\"> RAM</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s1\" class=\"w\"> SSD</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s1\" class=\"w\"> Screen</label>\n</div>\n<p class=\"fb ok\" aria-live=\"polite\"><strong>Correct!</strong> The keyboard is an input device. It brings your key presses into the computer.</p>\n<p class=\"fb no\" aria-live=\"polite\"><strong>Not quite.</strong> Input means bringing information in. Which part do your fingers touch?</p>\n</fieldset>\n\n<fieldset id=\"s2\">\n<legend><span class=\"step-n\">2</span>Processing: a program''s instructions turn each key press into a letter.</legend>\n<div class=\"opts\">\n<label class=\"opt\"><input type=\"radio\" name=\"s2\" class=\"w\"> Keyboard</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s2\" class=\"r\"> CPU</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s2\" class=\"w\"> RAM</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s2\" class=\"w\"> SSD</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s2\" class=\"w\"> Screen</label>\n</div>\n<p class=\"fb ok\" aria-live=\"polite\"><strong>Correct!</strong> The CPU follows the program''s instructions. It does the processing.</p>\n<p class=\"fb no\" aria-live=\"polite\"><strong>Not quite.</strong> Processing means following instructions. Which part is often called the \"brain\"?</p>\n</fieldset>\n\n<fieldset id=\"s3\">\n<legend><span class=\"step-n\">3</span>Memory: while you type, your name is held in fast, temporary working space.</legend>\n<div class=\"opts\">\n<label class=\"opt\"><input type=\"radio\" name=\"s3\" class=\"w\"> Keyboard</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s3\" class=\"w\"> CPU</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s3\" class=\"r\"> RAM</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s3\" class=\"w\"> SSD</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s3\" class=\"w\"> Screen</label>\n</div>\n<p class=\"fb ok\" aria-live=\"polite\"><strong>Correct!</strong> RAM holds the data the CPU is using right now. It is cleared when the power goes off.</p>\n<p class=\"fb no\" aria-live=\"polite\"><strong>Not quite.</strong> Look for the fast, short-term memory that forgets everything when the power goes off.</p>\n</fieldset>\n\n<fieldset id=\"s4\">\n<legend><span class=\"step-n\">4</span>Output: the letters of your name appear so you can see them.</legend>\n<div class=\"opts\">\n<label class=\"opt\"><input type=\"radio\" name=\"s4\" class=\"w\"> Keyboard</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s4\" class=\"w\"> CPU</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s4\" class=\"w\"> RAM</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s4\" class=\"w\"> SSD</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s4\" class=\"r\"> Screen</label>\n</div>\n<p class=\"fb ok\" aria-live=\"polite\"><strong>Correct!</strong> The screen is an output device. It shows you the result.</p>\n<p class=\"fb no\" aria-live=\"polite\"><strong>Not quite.</strong> Output means showing or playing the result. Where do you see your letters?</p>\n</fieldset>\n\n<fieldset id=\"s5\">\n<legend><span class=\"step-n\">5</span>Storage: you click Save, so your name is still there after the computer turns off.</legend>\n<div class=\"opts\">\n<label class=\"opt\"><input type=\"radio\" name=\"s5\" class=\"w\"> Keyboard</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s5\" class=\"w\"> CPU</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s5\" class=\"w\"> RAM</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s5\" class=\"r\"> SSD</label>\n<label class=\"opt\"><input type=\"radio\" name=\"s5\" class=\"w\"> Screen</label>\n</div>\n<p class=\"fb ok\" aria-live=\"polite\"><strong>Correct!</strong> The SSD (or hard drive) keeps files even when the power is off.</p>\n<p class=\"fb no\" aria-live=\"polite\"><strong>Not quite.</strong> RAM forgets when the power goes off. Which part keeps files for next time?</p>\n</fieldset>\n\n<h2>How the parts connect</h2>\n<p>Each part lights up when you get its step right.</p>\n<div class=\"machine\" aria-hidden=\"true\">\n<div class=\"part p-key\"><b>Keyboard</b><span>input</span></div>\n<div class=\"arrow\">&rarr;</div>\n<div class=\"part p-cpu\"><b>CPU</b><span>processing</span></div>\n<div class=\"arrow\">&rarr;</div>\n<div class=\"part p-scr\"><b>Screen</b><span>output</span></div>\n<div class=\"below\">\n<div class=\"part p-ram\"><b>RAM</b><span>working memory</span></div>\n<div class=\"part p-ssd\"><b>SSD</b><span>storage</span></div>\n<p class=\"two-way\">Both trade data with the CPU, in both directions.</p>\n</div>\n</div>\n<p class=\"sr\">Diagram: the keyboard sends input to the CPU, and the CPU sends output to the screen. RAM and the SSD both sit beside the CPU and trade data with it in both directions.</p>\n<div class=\"note\">\n<p><strong>Notice the connections.</strong> RAM and storage both sit beside the CPU and trade information back and forth with it. Storage is not a step that happens after every calculation. The CPU uses it when you open or save a file.</p>\n</div>\n<p class=\"fb ok done\" aria-live=\"polite\"><strong>You traced the whole action!</strong> Input, processing, memory, output and storage all worked together. A program told each part what to do with your data.</p>\n</main>\n</body>\n</html>\n","instructions":"Put the computer parts in order and trace what happens when you type and save your work. Click \"Mark as done\" when you finish.","reports_score":false}'::jsonb)
