   '{"prompt":"You save an essay and turn off your laptop. Which part keeps the essay so it is still there tomorrow?","choices":[{"id":"a","label":"The SSD or hard drive (storage)"},{"id":"b","label":"RAM (memory)"},{"id":"c","label":"The mouse"},{"id":"d","label":"The screen"}],"answer":"a","explanation":"RAM only holds what you are using right now and is cleared when the power goes off. Storage keeps files."}'::jsonb)
