insert into activities (id, lesson_id, position, type, concept, points, counts_toward_unlock, content) values
  ('1909aa19-1a70-5484-8bc0-03ad0c056b47', 'a4576df6-76de-548b-b906-b1040b033f3d', 2, 'content', 'early vs modern computers', 0, true,
   '{"markdown":"## Then vs. now\n\nThe Difference Engine used **gears**. A modern processor uses tiny **electronic circuits**.\nBoth automate calculations using physical parts. But a lot has changed.\n\n- **Size:** some early computers filled a whole room. Today, a much more powerful computer fits in your pocket.\n- **Speed:** modern computers are far faster and more powerful.\n- **Tasks:** early computers did basic calculations. Modern computers can run many different programs: games, video, maps, and more.\n- **Input:** early computers needed manual input with punch cards or switches. Today we type, tap, click and talk.\n\n### Computers hiding in plain sight\n\nPhones, tablets and laptops are computers. So are game consoles, smart TVs, car dashboards, microwaves and digital watches.\nCan you think of another computer you use every day?","title":"Then vs. now"}'::jsonb)
