insert into activities (id, lesson_id, position, type, concept, points, counts_toward_unlock, content) values
  ('6f5d1001-22ba-5197-9a38-f06579a73b1e', 'a4576df6-76de-548b-b906-b1040b033f3d', 3, 'interactive_html', 'early vs modern computers', 1, true,
   '{"html":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>Then vs. Now</title>\n<style>\n:root{--accent:#5b2a86;--accent-soft:#f3ecf9;--ink:#1b1b22;--muted:#464654;--line:#c4c4cf;--bg:#fff;--panel:#f5f5f8;--ok:#14532d;--ok-bg:#e4f4e9;--no:#8a1c1c;--no-bg:#fcebeb;--focus:#1d4ed8;color-scheme:light}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%}\nbody{margin:0;background:var(--bg);color:var(--ink);font:1.0625rem/1.55 system-ui,-apple-system,\"Segoe UI\",Roboto,Arial,sans-serif}\nmain{max-width:52rem;margin:0 auto;padding:16px 16px 28px}\nh1{font-size:1.5rem;line-height:1.25;margin:.25rem 0 .5rem}\nh2{font-size:1.2rem;line-height:1.3;margin:1.5rem 0 .5rem}\np{margin:.5rem 0}\nul,ol{margin:.5rem 0;padding-left:1.4rem}\n.kicker{margin:0;font-size:1rem;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--accent)}\n.lede{color:var(--muted)}\n.note{background:var(--panel);border-radius:12px;padding:12px 14px;margin:12px 0}\n.note>:first-child{margin-top:0}.note>:last-child{margin-bottom:0}\nfieldset{border:1px solid var(--line);border-radius:12px;padding:12px 14px 14px;margin:0 0 16px;min-width:0}\nlegend{float:left;width:100%;padding:0;margin:0 0 4px;font-weight:700;line-height:1.4}\nlegend+*{clear:both}\n.opts{display:grid;grid-template-columns:repeat(auto-fill,minmax(8.5rem,1fr));gap:8px;margin-top:8px}\n.opt{display:flex;align-items:center;gap:10px;min-height:48px;padding:8px 12px;border:2px solid var(--line);border-radius:10px;cursor:pointer;background:var(--bg);line-height:1.3}\n.opt input{width:22px;height:22px;margin:0;flex:none;accent-color:var(--accent);cursor:pointer}\n.opt:hover{border-color:var(--accent)}\n.opt:has(input:checked){border-color:var(--accent);background:var(--accent-soft)}\n.opt:has(.r:checked){border-color:var(--ok);background:var(--ok-bg)}\n.opt:has(.w:checked){border-color:var(--no);background:var(--no-bg)}\ninput:focus-visible{outline:3px solid var(--focus);outline-offset:2px}\n.opt:has(input:focus-visible){outline:3px solid var(--focus);outline-offset:2px}\n.fb{display:none;margin:10px 0 0;padding:10px 12px;border-radius:8px;border-left:6px solid}\n.fb.ok{background:var(--ok-bg);color:var(--ok);border-color:var(--ok)}\n.fb.no{background:var(--no-bg);color:var(--no);border-color:var(--no)}\n.fb.maybe{background:var(--accent-soft);color:var(--accent);border-color:var(--accent)}\n.sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}\n@media (prefers-reduced-motion:reduce){*,*::before,*::after{transition:none!important;animation:none!important}}\nfieldset:has(.r:checked)>.fb.ok,fieldset:has(.w:checked)>.fb.no{display:block}\n.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,34rem),1fr));gap:16px;margin:16px 0}\n.fc{display:flex;flex-direction:column;gap:8px}\n.fc>input{position:absolute;opacity:0;width:1px;height:1px;margin:0}\n.card{perspective:1200px;flex:1}\n.inner{display:grid;height:100%;transition:transform .5s ease;transform-style:preserve-3d}\n.face{grid-area:1/1;padding:14px 16px;border-radius:14px;backface-visibility:hidden;-webkit-backface-visibility:hidden;transition:visibility 0s .25s}\n.face h2{margin:0 0 6px}\n.front{display:flex;flex-direction:column;background:var(--accent-soft);border:2px solid var(--accent)}\n.front .guess{flex:1}\n.front .q{font-size:1.1rem}\n.guess{margin-top:10px}.guess>div{padding:8px 10px;border:2px dashed var(--accent);border-radius:10px;background:var(--bg)}.guess p{font-size:1.5rem;font-weight:700;color:var(--accent);line-height:1.2}\n.back{background:var(--bg);border:2px solid var(--accent);transform:rotateY(180deg);visibility:hidden}\n.cols{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.cols h3{margin:0 0 2px;font-size:1rem;color:var(--accent)}\n.cols p{margin:0}\n.fc>input:checked~.card .inner{transform:rotateY(180deg)}\n.fc>input:checked~.card .back{visibility:visible}\n.fc>input:checked~.card .front{visibility:hidden}\n.btn{display:flex;align-items:center;justify-content:center;min-height:48px;padding:8px 16px;border-radius:10px;background:var(--accent);color:#fff;font-weight:700;cursor:pointer;user-select:none}\n.btn:hover{background:#45206a}\n.fc>input:focus-visible~.btn{outline:3px solid var(--focus);outline-offset:3px}\n.btn .hide,.fc>input:checked~.btn .show{display:none}\n.fc>input:checked~.btn .hide{display:inline}\n@media (max-width:380px){.cols{grid-template-columns:1fr}}\n</style>\n</head>\n<body>\n<main>\n<p class=\"kicker\">AI Academy - Module 1</p>\n<h1>Then vs. Now</h1>\n<div class=\"note\">\n<p>Charles Babbage proposed the <strong>Difference Engine</strong> in 1822. It was a mechanical calculating engine made of gears and number wheels.</p>\n<p>It had one job: working out tables of numbers. It was not a general-purpose computer like the phone or laptop you use today.</p>\n</div>\n<p>For each card, <strong>predict first</strong> with a partner. Then flip the card to check.</p>\n\n<div class=\"cards\">\n<div class=\"fc\">\n<input type=\"checkbox\" id=\"c1\">\n<div class=\"card\"><div class=\"inner\">\n<div class=\"face front\"><h2>Size</h2><p class=\"q\">How big and heavy is each machine?</p><div class=\"cols guess\" aria-hidden=\"true\"><div><h3>Difference Engine</h3><p>?</p></div><div><h3>Phone or laptop</h3><p>?</p></div></div></div>\n<div class=\"face back\"><h2>Size</h2><div class=\"cols\">\n<div><h3>Difference Engine</h3><p>Babbage never finished the 1822 design. His later Difference Engine No. 2 was built from his plans in London in 1991. It weighs about 5 tons and has about 8,000 parts.</p></div>\n<div><h3>Phone or laptop</h3><p>A phone is about 200 grams and fits in a pocket. A laptop is about 1 to 2 kilograms. You would need about 25,000 phones to match 5 tons!</p></div>\n</div></div>\n</div></div>\n<label for=\"c1\" class=\"btn\"><span class=\"show\">Flip to see the facts</span><span class=\"hide\">Flip back</span><span class=\"sr\"> about size</span></label>\n</div>\n\n<div class=\"fc\">\n<input type=\"checkbox\" id=\"c2\">\n<div class=\"card\"><div class=\"inner\">\n<div class=\"face front\"><h2>Speed and tasks</h2><p class=\"q\">How fast is each one, and how many different jobs can it do?</p><div class=\"cols guess\" aria-hidden=\"true\"><div><h3>Difference Engine</h3><p>?</p></div><div><h3>Phone or laptop</h3><p>?</p></div></div></div>\n<div class=\"face back\"><h2>Speed and tasks</h2><div class=\"cols\">\n<div><h3>Difference Engine</h3><p>Does one kind of job: calculating number tables, step by step. It only moves as fast as a person can turn its handle.</p></div>\n<div><h3>Phone or laptop</h3><p>Does billions of steps every second. It runs many different programs: games, maps, video calls, music and AI apps.</p></div>\n</div></div>\n</div></div>\n<label for=\"c2\" class=\"btn\"><span class=\"show\">Flip to see the facts</span><span class=\"hide\">Flip back</span><span class=\"sr\"> about speed and tasks</span></label>\n</div>\n\n<div class=\"fc\">\n<input type=\"checkbox\" id=\"c3\">\n<div class=\"card\"><div class=\"inner\">\n<div class=\"face front\"><h2>Input method</h2><p class=\"q\">How does a person give each machine information?</p><div class=\"cols guess\" aria-hidden=\"true\"><div><h3>Difference Engine</h3><p>?</p></div><div><h3>Phone or laptop</h3><p>?</p></div></div></div>\n<div class=\"face back\"><h2>Input method</h2><div class=\"cols\">\n<div><h3>Difference Engine</h3><p>A person sets the starting numbers by turning number wheels by hand, then cranks the handle. Answers show on the wheels.</p></div>\n<div><h3>Phone or laptop</h3><p>Touchscreen, keyboard, mouse or trackpad, your voice through the microphone, and the camera.</p></div>\n</div></div>\n</div></div>\n<label for=\"c3\" class=\"btn\"><span class=\"show\">Flip to see the facts</span><span class=\"hide\">Flip back</span><span class=\"sr\"> about input method</span></label>\n</div>\n\n<div class=\"fc\">\n<input type=\"checkbox\" id=\"c4\">\n<div class=\"card\"><div class=\"inner\">\n<div class=\"face front\"><h2>What is inside</h2><p class=\"q\">What parts do the calculating?</p><div class=\"cols guess\" aria-hidden=\"true\"><div><h3>Difference Engine</h3><p>?</p></div><div><h3>Phone or laptop</h3><p>?</p></div></div></div>\n<div class=\"face back\"><h2>What is inside</h2><div class=\"cols\">\n<div><h3>Difference Engine</h3><p>Metal gears, rods and number wheels that you can watch move.</p></div>\n<div><h3>Phone or laptop</h3><p>Electronic circuits on a chip, with billions of tiny switches called transistors.</p></div>\n</div></div>\n</div></div>\n<label for=\"c4\" class=\"btn\"><span class=\"show\">Flip to see the facts</span><span class=\"hide\">Flip back</span><span class=\"sr\"> about what is inside</span></label>\n</div>\n</div>\n\n<h2>What stayed the same?</h2>\n<div class=\"note\">\n<p>Both machines <strong>automate calculation using physical parts</strong>: gears then, electronic circuits now.</p>\n<p>The biggest change: a modern computer can run many different programs, not just one kind of calculation.</p>\n</div>\n<p><strong>Your turn:</strong> share one difference and one similarity with your partner.</p>\n</main>\n</body>\n</html>\n","instructions":"Compare an early computer with a device you use today. Click \"Mark as done\" when you finish.","reports_score":false}'::jsonb)
