insert into activities (id, lesson_id, position, type, concept, points, counts_toward_unlock, content) values
  ('36060d3f-f3c8-5f69-baf2-2420ae5cd65f', 'abc4d63a-7ff8-5b87-8697-901187822760', 5, 'check', 'AI or not', 1, true,
   '{"prompt":"Is a thermostat AI?","choices":[{"id":"a","label":"Always: it turns on by itself, so it is AI"},{"id":"b","label":"Never: thermostats cannot use AI"},{"id":"c","label":"It depends: a basic one follows a set temperature rule, but a learning thermostat may use AI"},{"id":"d","label":"Only if it is a famous brand"}],"answer":"c","explanation":"Doing something automatically is not proof of AI. A basic thermostat follows one fixed rule. A learning thermostat that finds patterns in your schedule may use AI."}'::jsonb)
