insert into activities (id, lesson_id, position, type, concept, points, counts_toward_unlock, content) values
  ('0e248a3e-4a43-5912-8084-1627cfb888c0', 'abc4d63a-7ff8-5b87-8697-901187822760', 7, 'check', 'AI limits', 1, true,
   '{"prompt":"A chatbot tells you a fact for your history project. What is the best next step?","choices":[{"id":"a","label":"Use it right away, because AI does not make mistakes"},{"id":"b","label":"Ask the chatbot if it is sure, and trust whatever it says"},{"id":"c","label":"Change a few words so it looks like your own"},{"id":"d","label":"Check the fact with a trusted source before you use it"}],"answer":"d","explanation":"AI can state wrong facts confidently. Checking a trusted source is how you know the fact is right."}'::jsonb)
