insert into activities (id, lesson_id, position, type, concept, points, counts_toward_unlock, content) values
  ('7e5729bd-c1c5-55a7-a214-db65fbbbc0a0', 'abc4d63a-7ff8-5b87-8697-901187822760', 8, 'content', 'common AI technologies', 0, true,
   '{"markdown":"## Common AI technologies\n\nAI is more than chatbots. You probably use these every week:\n\n- **Smart assistants** like Siri or Alexa understand your voice and answer questions.\n- **Recommendation systems** suggest videos, songs, or products based on patterns in what you and others liked.\n- **Chatbots** write answers to your messages using patterns learned from lots of text.\n- **Facial recognition** finds and matches faces in photos, for example to unlock a phone.\n- **Navigation apps** predict traffic and suggest the fastest route.\n\n### Your turn\n\nPick one of these. Look it up with a trusted source and find:\n\n1. How it works, in your own words\n2. One surprising fact\n3. Where you found the information\n\nThen ask yourself: what AI applications do you use in your everyday life?","title":"Common AI technologies"}'::jsonb)
