  ('37f58c6d-8228-588d-b285-b17a42101257', 'abc4d63a-7ff8-5b87-8697-901187822760', 9, 'check', 'common AI technologies', 1, true,
   '{"prompt":"A navigation app tells you to take a different road because of traffic ahead. What is the AI doing?","choices":[{"id":"a","label":"Reading the driver''s mind"},{"id":"b","label":"Using patterns in traffic data to predict the fastest route"},{"id":"c","label":"Following one rule that never changes"},{"id":"d","label":"Nothing: maps never use AI"}],"answer":"b","explanation":"Navigation apps use data about traffic and patterns from past trips to predict which route will be fastest."}'::jsonb)
