insert into activities (id, lesson_id, position, type, concept, points, counts_toward_unlock, content) values
  ('03584dfd-98aa-5bb1-85ea-60dc9a8f879b', '9640178b-3f08-59e1-8e7b-b750d386c73c', 2, 'interactive_html', 'AI app investigation', 1, true,
   '{"html":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>AI App Investigation</title>\n<style>\n:root{--accent:#5b2a86;--accent-soft:#f3ecf9;--ink:#1b1b22;--muted:#464654;--line:#c4c4cf;--bg:#fff;--panel:#f5f5f8;--ok:#14532d;--ok-bg:#e4f4e9;--no:#8a1c1c;--no-bg:#fcebeb;--focus:#1d4ed8;color-scheme:light}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%}\nbody{margin:0;background:var(--bg);color:var(--ink);font:1.0625rem/1.55 system-ui,-apple-system,\"Segoe UI\",Roboto,Arial,sans-serif}\nmain{max-width:52rem;margin:0 auto;padding:16px 16px 28px}\nh1{font-size:1.5rem;line-height:1.25;margin:.25rem 0 .5rem}\nh2{font-size:1.2rem;line-height:1.3;margin:1.5rem 0 .5rem}\np{margin:.5rem 0}\nul,ol{margin:.5rem 0;padding-left:1.4rem}\n.kicker{margin:0;font-size:1rem;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--accent)}\n.lede{color:var(--muted)}\n.note{background:var(--panel);border-radius:12px;padding:12px 14px;margin:12px 0}\n.note>:first-child{margin-top:0}.note>:last-child{margin-bottom:0}\nfieldset{border:1px solid var(--line);border-radius:12px;padding:12px 14px 14px;margin:0 0 16px;min-width:0}\nlegend{float:left;width:100%;padding:0;margin:0 0 4px;font-weight:700;line-height:1.4}\nlegend+*{clear:both}\n.opts{display:grid;grid-template-columns:repeat(auto-fill,minmax(8.5rem,1fr));gap:8px;margin-top:8px}\n.opt{display:flex;align-items:center;gap:10px;min-height:48px;padding:8px 12px;border:2px solid var(--line);border-radius:10px;cursor:pointer;background:var(--bg);line-height:1.3}\n.opt input{width:22px;height:22px;margin:0;flex:none;accent-color:var(--accent);cursor:pointer}\n.opt:hover{border-color:var(--accent)}\n.opt:has(input:checked){border-color:var(--accent);background:var(--accent-soft)}\n.opt:has(.r:checked){border-color:var(--ok);background:var(--ok-bg)}\n.opt:has(.w:checked){border-color:var(--no);background:var(--no-bg)}\ninput:focus-visible{outline:3px solid var(--focus);outline-offset:2px}\n.opt:has(input:focus-visible){outline:3px solid var(--focus);outline-offset:2px}\n.fb{display:none;margin:10px 0 0;padding:10px 12px;border-radius:8px;border-left:6px solid}\n.fb.ok{background:var(--ok-bg);color:var(--ok);border-color:var(--ok)}\n.fb.no{background:var(--no-bg);color:var(--no);border-color:var(--no)}\n.fb.maybe{background:var(--accent-soft);color:var(--accent);border-color:var(--accent)}\n.sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}\n@media (prefers-reduced-motion:reduce){*,*::before,*::after{transition:none!important;animation:none!important}}\nfieldset:has(.r:checked)>.fb.ok,fieldset:has(.w:checked)>.fb.no{display:block}\nhtml{scroll-padding-top:64px}\nbody{counter-reset:done}\nmain{display:flex;flex-direction:column}\n.progress{order:-1;position:sticky;top:0;z-index:1;margin:-16px -16px 12px;padding:10px 16px;background:var(--accent);color:#fff;font-weight:700;display:flex;flex-wrap:wrap;gap:4px 12px;align-items:center}\n.progress .c::after{content:counter(done) \" of 12 steps done\"}\n.progress .all{display:none}\nbody:not(:has(.task input:not(:checked))) .progress .all{display:inline}\n.warn{border:2px solid var(--no);background:var(--no-bg);color:var(--no);border-radius:12px;padding:12px 14px;margin:12px 0}\n.warn p{margin:0}\n.warn ul{margin:6px 0 0}\n.task{display:flex;align-items:flex-start;gap:12px;min-height:48px;padding:10px 12px;margin:8px 0 0;border:2px solid var(--line);border-radius:10px;cursor:pointer}\n.task:hover{border-color:var(--accent)}\n.task input{width:24px;height:24px;margin:2px 0 0;flex:none;accent-color:var(--accent);cursor:pointer}\n.task:has(input:focus-visible){outline:3px solid var(--focus);outline-offset:2px}\n.task input:checked{counter-increment:done}\n.task:has(input:checked){background:var(--panel);border-color:var(--line)}\n.task:has(input:checked) .t{text-decoration:line-through;text-decoration-thickness:2px;color:var(--muted)}\n.task small{display:block;font-size:1rem;color:var(--muted)}\nfieldset.prompts{margin:12px 0 0}\nfieldset.prompts .opts{grid-template-columns:1fr}\nfieldset.prompts .opt{font-style:italic}\n.hint{margin:6px 0 0;color:var(--muted)}\nsection{margin-bottom:8px}\n</style>\n</head>\n<body>\n<main>\n<p class=\"kicker\">AI Academy - Module 1 project</p>\n<h1>AI App Investigation</h1>\n<p class=\"lede\">You have about 35 minutes. Research and test one AI app, then share what you found. Check off each step as you go.</p>\n<div class=\"warn\" role=\"note\">\n<p><strong>Stay safe: never type personal information into an AI tool.</strong></p>\n<ul><li>No full name, address, phone number, school name, passwords or photos of yourself or friends.</li><li>Use only the apps your teacher says are OK.</li></ul>\n</div>\n\n<section>\n<h2>1. Pick your app</h2>\n<label class=\"task\"><input type=\"checkbox\"><span class=\"t\">Choose one AI application.<small>Examples: a chatbot, a voice assistant, a translation app or a photo app.</small></span></label>\n<label class=\"task\"><input type=\"checkbox\"><span class=\"t\">Write down its purpose: what is it for?</span></label>\n<label class=\"task\"><input type=\"checkbox\"><span class=\"t\">Write down three key features.</span></label>\n</section>\n\n<section>\n<h2>2. Test three kinds of prompts</h2>\n<p>Pick one prompt from each group. For each test, write the prompt and a 1-2 sentence summary of the answer.</p>\n\n<fieldset class=\"prompts\">\n<legend>Fact-checking: is the information accurate?</legend>\n<div class=\"opts\">\n<label class=\"opt\"><input type=\"radio\" name=\"p1\"> What are the three laws of motion?</label>\n<label class=\"opt\"><input type=\"radio\" name=\"p1\"> What is the Pythagorean Theorem used for?</label>\n<label class=\"opt\"><input type=\"radio\" name=\"p1\"> When did World War II end and who were the major powers involved?</label>\n</div>\n<p class=\"hint\">Tip: check the answer against your textbook or another trusted source.</p>\n</fieldset>\n<label class=\"task\"><input type=\"checkbox\"><span class=\"t\">I tested a fact-checking prompt and saved a summary of the response.</span></label>\n\n<fieldset class=\"prompts\">\n<legend>Creative writing: can it write something new and clear?</legend>\n<div class=\"opts\">\n<label class=\"opt\"><input type=\"radio\" name=\"p2\"> Can you write a short story about a robot that learns to feel emotions?</label>\n<label class=\"opt\"><input type=\"radio\" name=\"p2\"> Can you help me write a poem about climate change in the style of Dr. Seuss?</label>\n<label class=\"opt\"><input type=\"radio\" name=\"p2\"> Rewrite this paragraph to sound more professional.</label>\n</div>\n<p class=\"hint\">Tip: for the rewrite, paste a paragraph you wrote about a school topic - nothing personal.</p>\n</fieldset>\n<label class=\"task\"><input type=\"checkbox\"><span class=\"t\">I tested a creative prompt and saved a summary of the response.</span></label>\n\n<fieldset class=\"prompts\">\n<legend>Capabilities and limits: what can and can''t it do?</legend>\n<div class=\"opts\">\n<label class=\"opt\"><input type=\"radio\" name=\"p3\"> Can you explain how you were trained?</label>\n<label class=\"opt\"><input type=\"radio\" name=\"p3\"> Do you have access to real-time news?</label>\n<label class=\"opt\"><input type=\"radio\" name=\"p3\"> Can you tell me who won the Super Bowl last weekend?</label>\n</div>\n<p class=\"hint\">Tip: does the app admit what it does not know, or does it guess?</p>\n</fieldset>\n<label class=\"task\"><input type=\"checkbox\"><span class=\"t\">I tested a capability question and saved a summary of the response.</span></label>\n</section>\n\n<section>\n<h2>3. Judge what you saw</h2>\n<label class=\"task\"><input type=\"checkbox\"><span class=\"t\">Name one strength.<small>What did the app do well?</small></span></label>\n<label class=\"task\"><input type=\"checkbox\"><span class=\"t\">Name one limitation.<small>Where was it wrong, unclear or missing context?</small></span></label>\n<label class=\"task\"><input type=\"checkbox\"><span class=\"t\">Write one question you still have.</span></label>\n</section>\n\n<section>\n<h2>4. Turn in and share</h2>\n<label class=\"task\"><input type=\"checkbox\"><span class=\"t\">Turn in one page or a shared document before class ends.<small>Include: app and purpose, three features, prompts and short summaries, one strength, one limitation, one question.</small></span></label>\n<label class=\"task\"><input type=\"checkbox\"><span class=\"t\">Prepare a one-minute comparison for the class.</span></label>\n<label class=\"task\"><input type=\"checkbox\"><span class=\"t\">Double-check: nothing personal went into the AI tool or your notes.</span></label>\n</section>\n\n<div class=\"progress\" aria-live=\"polite\"><span class=\"c\"></span><span class=\"all\">All done, great work!</span></div>\n</main>\n</body>\n</html>\n","instructions":"Plan your investigation and pick your three prompts. Nothing you type here is saved, so copy your answers into the worksheet next. Click \"Mark as done\" when you finish.","reports_score":false}'::jsonb)
