   '{"items":[{"id":"q1","concept":"computer parts","prompt":"The CPU is sometimes called the computer''s \"brain\". What does it do?","choices":[{"id":"a","label":"Shows pictures on the screen"},{"id":"b","label":"Keeps files when the power is off"},{"id":"c","label":"Follows a program''s instructions to process data"},{"id":"d","label":"Lets you type letters"}],"answer":"c"},{"id":"q2","concept":"binary","prompt":"What is a bit?","choices":[{"id":"a","label":"A single 0 or 1 that a computer uses to store information"},{"id":"b","label":"A small piece of the keyboard"},{"id":"c","label":"A type of computer screen"},{"id":"d","label":"A short video"}],"answer":"a"},{"id":"q3","concept":"early vs modern computers","prompt":"How did Charles Babbage''s Difference Engine work?","choices":[{"id":"a","label":"With a touch screen and apps"},{"id":"b","label":"With gears and wheels that calculated numbers"},{"id":"c","label":"With electronic circuits like a laptop"},{"id":"d","label":"With a steam engine that ran any program"}],"answer":"b"},{"id":"q4","concept":"early vs modern computers","prompt":"How did people give information to many early computers?","choices":[{"id":"a","label":"By talking to a voice assistant"},{"id":"b","label":"By tapping a touch screen"},{"id":"c","label":"With punch cards or switches"},{"id":"d","label":"Through Wi-Fi"}],"answer":"c"},{"id":"q5","concept":"what is AI","prompt":"Which task is an example of AI?","choices":[{"id":"a","label":"A lamp turning on when you flip a switch"},{"id":"b","label":"A clock showing the time"},{"id":"c","label":"A door that opens with a key"},{"id":"d","label":"A photo app recognizing which photos have a dog in them"}],"answer":"d"},{"id":"q6","concept":"AI or not","prompt":"Which of these is NOT AI, under ordinary assumptions?","choices":[{"id":"a","label":"A basic calculator"},{"id":"b","label":"A voice assistant like Siri"},{"id":"c","label":"A self-driving car"},{"id":"d","label":"Video recommendations"}],"answer":"a"},{"id":"q7","concept":"how AI learns","prompt":"You want to teach a computer to tell apples from oranges. What would machine learning use?","choices":[{"id":"a","label":"One rule: everything round is an apple"},{"id":"b","label":"Lots of labeled example photos of apples and oranges"},{"id":"c","label":"A faster keyboard"},{"id":"d","label":"A bigger screen"}],"answer":"b"},{"id":"q8","concept":"AI limits","prompt":"Which is a real limitation of AI tools?","choices":[{"id":"a","label":"They can never make text or images"},{"id":"b","label":"They always know today''s news"},{"id":"c","label":"They are perfect if they have enough data"},{"id":"d","label":"They can give wrong or unfair answers while sounding sure"}],"answer":"d"}],"title":"Show what you learned"}'::jsonb)
